-- SPIDER PROTECTOR | AQUI É TROPA SPIDER
-- Soucer aqui? JAMAIS! Seu código é protegido.
-- ============================================

local _d=""
local _a=96
local _b=207
local _abc="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local _out={}
local _buf=0
local _bits=0
for _i=1,#_d do
  local _ch=string.sub(_d,_i,_i)
  if _ch~="=" then
    local _v=string.find(_abc,_ch,1,true)-1
    _buf=bit32.bor(bit32.lshift(_buf,6),_v)
    _bits=_bits+6
    if _bits>=8 then
      _bits=_bits-8
      local _byte=bit32.band(bit32.rshift(_buf,_bits),255)
      _out[#_out+1]=string.char(bit32.bxor(bit32.bxor(_byte,_b),_a))
      _buf=bit32.band(_buf,bit32.lshift(1,_bits)-1)
    end
  end
end
local _src=table.concat(_out)
local _fn=loadstring or load
local _run=assert(_fn(_src))
_run()
pcall(function() game:GetService("StarterGui"):SetCore("SendNotification",{Title="SPIDER PROTECTOR",Text="AQUI É TROPA SPIDER! SOUCER AQUI? JAMAIS! 🕷️",Duration=5}) end)
local _spider_honeypot="SPIDER_HONEYPOT_cdeba6dd884f440f"
if _spider_honeypot=="SPIDER_HONEYPOT_TRIGGER" then warn("SPIDER PROTECTOR: honeypot acionado") end
